/bin/bash -lc "node check.js && node <<'NODE'
const assert = require('node:assert/strict');
const { parse_port } = require('./logic');
for (const value of [undefined, null, 80, true, {}, [], '+80', '1.0', '1e2', '0x50', '80 ', '80\\n', '\\n80', '80\\r\\n', '8\\t0', '000', '9'.repeat(1000)]) {
  assert.equal(parse_port(value), null);
}
for (const [value, expected] of [['00001', 1], ['00080', 80], ['0'.repeat(1000) + '65535', 65535]]) {
  assert.equal(parse_port(value), expected);
}
for (let port = 1; port <= 65535; port++) {
  assert.equal(parse_port(String(port)), port);
}
console.log('Existing checks and additional boundary, format, type, and full-range checks passed.');
NODE
"

